// ==========================================================
// 1. MECANISMO DE ESPERA Y CONTROL DE ERRORES
// ==========================================================
// Evita que el panel muestre un error en rojo si Grafana intenta
// dibujar el gráfico antes de recibir la respuesta de MySQL.
if (!context.panel.data.series || context.panel.data.series.length === 0) {
  return { title: { text: 'Esperando datos de procesos...' } };
}

// ==========================================================
// 2. EXTRACCIÓN DE DATOS BRUTOS DESDE GRAFANA
// ==========================================================
// Buscamos las columnas generadas por nuestro SQL y sacamos los valores en arrays
const fields = context.panel.data.series[0].fields;
const ids = fields.find(f => f.name === 'id').values;
const parent_ids = fields.find(f => f.name === 'parent_id').values;
const names = fields.find(f => f.name === 'name').values;
const cpus = fields.find(f => f.name === 'value').values;

let nodes = []; // Lista donde guardaremos los procesos
let links = []; // Lista donde guardaremos las relaciones

// ==========================================================
// 3. CONSTRUCCIÓN DEL GRAFO
// ==========================================================
for (let i = 0; i < ids.length; i++) {
  let id = String(ids[i]);
  let ppid = String(parent_ids[i]);
  let cpu = parseFloat(cpus[i]) || 0; // Si el valor es nulo, le ponemos 0 por seguridad
  let name = names[i];

  // --------------------------------------------------------
  // SEMÁFORO DE CONSUMO
  // --------------------------------------------------------
  // Por defecto, un proceso es Verde (Consumo normal / saludable)
  let nodeColor = '#32D74B';
  let borderColor = '#28A745';

  if (cpu > 40) {
    // Si consume más del 40%, cambia a ROJO ALERTA
    nodeColor = '#FF453A';
    borderColor = '#FF3B30';
  } else if (cpu > 15) {
    // Si consume más del 15%, cambia a AMARILLO PRECAUCIÓN
    nodeColor = '#FFD60A';
    borderColor = '#FFCC00';
  }

  // --------------------------------------------------------
  // TAMAÑO DINÁMICO
  // --------------------------------------------------------
  // Base 35px: Asegura que los procesos con 0% de CPU sigan siendo visibles.
  // cpu * 1.5: La bola crece proporcionalmente al consumo de CPU.
  let nodeSize = 35 + (cpu * 1.5);

  // Ponemos un límite de 120px para que un proceso al 100% no tape todo el panel
  if (nodeSize > 120) nodeSize = 120;

  // --------------------------------------------------------
  // INYECCIÓN DEL NODO
  // --------------------------------------------------------
  nodes.push({
    id: id,
    name: name,
    value: cpu.toFixed(2), // Guardamos el valor redondeado para mostrarlo luego
    symbolSize: nodeSize,
    itemStyle: {
      color: nodeColor,
      borderColor: borderColor,
      borderWidth: 2,
      shadowBlur: 15, // Efecto de iluminación/volumen 3D
      shadowColor: 'rgba(0,0,0,0.5)'
    },
    label: {
      show: true,
      position: 'bottom', // El nombre se escribe debajo de la bola, no la tapa
      distance: 5,        // Separación entre bola y texto
      color: '#ffffff',
      fontWeight: 'bold',
      formatter: '{b}\n{c} %', // {b}=Nombre, {c}=Valor(CPU). El \n crea dos líneas.
      textBorderColor: '#000000', // Borde negro al texto para que se lea siempre
      textBorderWidth: 3,
      lineHeight: 16
    }
  });

  // --------------------------------------------------------
  // CREACIÓN DE LAS CONEXIONES 
  // --------------------------------------------------------
  // El PID 1 (systemd) es el origen de todos, no tiene un padre visible.
  // Si NO es el proceso 1, le decimos a ECharts que dibuje una flecha 
  // desde el Padre (source) hacia este proceso Hijo (target).
  if (id !== "1") {
    links.push({
      source: ppid,
      target: id
    });
  }
}

// ==========================================================
// 4. CONFIGURACIÓN DEL MOTOR DE FÍSICAS
// ==========================================================
return {
  backgroundColor: 'transparent',

  // Ventana flotante interactiva al pasar el ratón por un proceso
  tooltip: {
    backgroundColor: 'rgba(20, 22, 25, 0.9)', // Fondo oscuro profesional
    borderColor: '#444',
    textStyle: { color: '#fff' },
    formatter: function (params) {
      if (params.dataType === 'node') {
        // Código HTML inyectado para mostrar el Nombre, PID y la CPU teñida del color del semáforo
        return `<b>${params.data.name}</b><br/>PID: ${params.data.id}<br/>CPU: <span style="color:${params.data.itemStyle.color}; font-weight:bold;">${params.data.value}%</span>`;
      }
      return '';
    }
  },

  series: [
    {
      type: 'graph',

      // 'force' enciende el motor de colisiones y gravedades
      layout: 'force',
      force: {
        repulsion: 350,        // Los procesos se comportan como imanes repeliéndose para no solaparse
        edgeLength: [60, 130], // La conexión actúa como una goma elástica que mide entre 60 y 130 píxeles
        gravity: 0.05          // Gravedad débil hacia el centro para que el árbol no se salga de la pantalla
      },

      roam: true,       // Permite al usuario hacer scroll (zoom) y mover el mapa general
      draggable: true,  // Permite arrastrar bolas individuales para reorganizar el árbol

      // Dibujamos una punta de flecha ('arrow') al final de cada conexión
      edgeSymbol: ['none', 'arrow'],
      edgeSymbolSize: [0, 10],

      data: nodes, // Cargamos la lista de bolas
      links: links, // Cargamos la lista de conexiones

      // Estilo de las ramas: gris, grosor 1.5 y ligeramente curvadas para darle un toque orgánico
      lineStyle: {
        color: '#8e94a1',
        width: 1.5,
        curveness: 0.2,
        opacity: 0.7
      }
    }
  ]
};

