visualEditor.code:
// ==========================================================
// 1. CONTROL DE ERRORES
// ==========================================================
// Grafana a veces ejecuta este código antes de que la base de datos responda.
// Si no hacemos esto, el panel daría un error rojo. 
// Si la serie de datos está vacía, muestra este mensaje y espera.
if (!context.panel.data.series || context.panel.data.series.length === 0) {
  return { title: { text: 'Buscando vecinos en la red...' } };
}

// ==========================================================
// 2. EXTRACCIÓN DE DATOS DE GRAFANA
// ==========================================================
// Grafana nos pasa los datos del SQL en un objeto interno llamado 'context'.
const fields = context.panel.data.series[0].fields;

// Buscamos las columnas que llamamos 'target' (IPs) y 'mac_address' (MACs) en nuestro SQL
// y extraemos todos sus valores en forma de lista (Array).
const targets = fields.find(f => f.name === 'target').values;
const macs = fields.find(f => f.name === 'mac_address').values;

// ==========================================================
// 3. CREACIÓN DEL NODO CENTRAL
// ==========================================================
// Creamos la primera 'bola' del grafo. Tu máquina.
let nodes = [{
  id: 'Mi Servidor',
  name: 'Mi Servidor\n 10.0.31.8', // \n hace un salto de línea para que quede bonito
  symbolSize: 65,                  // La hacemos más grande que el resto (65px)
  itemStyle: {
    color: '#007AFF',              // Azul principal
    borderColor: '#0056b3',        // Borde azul oscuro
    borderWidth: 2,
    shadowBlur: 15,                // Le da un efecto de brillo neón
    shadowColor: 'rgba(0,122,255,0.5)'
  },
  label: { show: true, position: 'bottom', color: '#fff', fontWeight: 'bold' }
}];

let links = []; // Aquí guardaremos las "cuerdas" que unen los nodos

// ==========================================================
// 4. BUCLE DE CREACIÓN DE VECINOS
// ==========================================================
// Recorremos la lista de IPs que sacamos en el paso 2
for (let i = 0; i < targets.length; i++) {
  let ip = targets[i];
  let mac = macs[i];

  // Control de duplicados: Si la IP ya está en nuestra lista de 'nodes', la ignoramos.
  // Esto evita que se dibujen dos bolas para la misma IP si la BD tiene datos repetidos.
  if (!nodes.find(n => n.id === ip)) {

    // Añadimos la 'bola' del vecino (Color Verde)
    nodes.push({
      id: ip,
      name: ip + '\n' + mac, // Mostramos IP arriba y MAC abajo
      symbolSize: 45,        // Más pequeña que el servidor central
      itemStyle: { color: '#32D74B', borderColor: '#28A745', borderWidth: 2 },
      label: { show: true, position: 'bottom', color: '#fff', fontSize: 11 }
    });

    // Creamos la conexión. 
    // Le decimos a ECharts que tire una línea desde 'Mi Servidor' hasta esta 'ip'
    links.push({ source: 'Mi Servidor', target: ip });
  }
}

// ==========================================================
// 5. CONFIGURACIÓN DEL MOTOR DE FÍSICAS Y RENDERIZADO
// ==========================================================
return {
  backgroundColor: 'transparent', // Fondo transparente
  tooltip: {
    formatter: '{b}' // {b} es una variable interna de ECharts que significa "Muestra el nombre (name) de la bola al pasar el ratón"
  },
  series: [{
    type: 'graph',

    // 'force' activa el motor de físicas de JavaScript
    layout: 'force',
    force: {
      repulsion: 500,   // Como si fueran imanes del mismo polo. Cuanto mayor, más se alejan las bolas entre sí.
      edgeLength: 150,  // La longitud ideal de la "cuerda" (link) que las une.
      gravity: 0.1      // Atrae a todos los nodos suavemente hacia el centro de la pantalla para que no se salgan del marco.
    },

    roam: true,       // Permite al usuario hacer Zoom y arrastrar todo el mapa
    draggable: true,  // Permite al usuario coger una bola con el ratón y moverla (física interactiva)

    data: nodes,      // Le inyectamos el Array de bolas que hemos construido
    links: links,     // Le inyectamos el Array de cuerdas

    // Estilo de la cuerda: gris, grosor 2, ligeramente curva (0.2) y discontinua (dashed)
    lineStyle: { color: '#8e94a1', width: 2, curveness: 0.2, type: 'dashed' }
  }]
};
